/**
	Util function to set error response.

	@param {Any} statusCode - 
	@param {Any} errorMessage - 
	@param {Any} map - 
	@return {Any} 
*/
function setErrorResponse(statusCode, errorMessage, map) {
    var targetMap = map || responseMap;

    var json = createJsonResponse(statusCode, errorMessage);
    targetMap.put('status', String(statusCode));
    targetMap.put('responseStatusCode', statusCode);
    targetMap.put('fhirResponse', json);
    targetMap.put('finalResponse', json);
}
/**
 Util function to generate json string wit hstatus and message
*/
function createJsonResponse(status, message) {
    return JSON.stringify({ status: status, message: message });
}

/**
	Server-wide, thread-safe cache of COMPILED XML artefacts (XSD Schema, XSLT Templates),
	loaded from Lookup Manager group "SchemaFiles". Nothing is written to disk.

	Only immutable, thread-safe objects are cached. Callers must create a new
	Validator / Transformer per message from the cached object:
	    getCompiledSchema('CDA.xsd').newValidator().validate(source);
	    var transformer = getCompiledXslt('cda-phi-filter-epic').newTransformer();

	Each artefact is compiled once per server (first caller compiles, concurrent callers
	wait for that result). A failed compile is not cached, so the next call retries.
	Schema files are fixed; if one is changed, restart the server or call clearXmlCache().
*/
var TECHBD_XML_CACHE_KEY = 'techbd.xmlCache';
var TECHBD_XML_BASE_URI = 'file:///techbd-lookup/'; // stable virtual systemId for include resolution; never read from disk

/**
	Returns the shared ConcurrentHashMap, creating it exactly once (lock on the globalMap singleton).
*/
function xmlCache() {
    var cache = globalMap.get(TECHBD_XML_CACHE_KEY);
    if (cache != null) return cache;
    var init = new Packages.org.mozilla.javascript.Synchronizer(function () {
        var c = globalMap.get(TECHBD_XML_CACHE_KEY);
        if (c == null) {
            c = new java.util.concurrent.ConcurrentHashMap();
            globalMap.put(TECHBD_XML_CACHE_KEY, c);
        }
        return c;
    }, globalMap);
    return init();
}

/**
	Reads a Lookup Manager "SchemaFiles" entry as a JS string, or null if missing/empty.
*/
function lookupSchemaFileText(key) {
    var raw = LookupHelper.get("SchemaFiles", key);
    if (raw == null) return null;
    var text = (typeof raw === "object" && raw.content) ? String(raw.content) : String(raw);
    return text.trim().length > 0 ? text : null;
}

function xmlRefBaseName(ref) {
    return String(ref).replace(/^.*[\/\\]/, '');
}

/**
	Compiled XSD (javax.xml.validation.Schema). Includes/imports are resolved from Lookup by file name.
	@param {String} rootXsdKey - Lookup key of the root schema, e.g. "CDA.xsd"
*/
function getCompiledSchema(rootXsdKey) {
    var rootKey = xmlRefBaseName(rootXsdKey);
    return xmlCache().computeIfAbsent('xsd:' + rootKey, new java.util.function.Function({
        apply: function () {
            var rootText = lookupSchemaFileText(rootKey);
            if (rootText == null) throw new Error("LookupManager: Missing XSD in SchemaFiles: " + rootKey);

            var ls = org.w3c.dom.bootstrap.DOMImplementationRegistry.newInstance().getDOMImplementation("LS");
            var sf = javax.xml.validation.SchemaFactory.newInstance(javax.xml.XMLConstants.W3C_XML_SCHEMA_NS_URI);
            sf.setResourceResolver(new org.w3c.dom.ls.LSResourceResolver({
                resolveResource: function (type, namespaceURI, publicId, systemId, baseURI) {
                    var name = xmlRefBaseName(systemId);
                    var text = lookupSchemaFileText(name);
                    if (text == null) throw new Error("LookupManager: Missing XSD in SchemaFiles: " + name);
                    var input = ls.createLSInput();
                    input.setStringData(text);
                    input.setSystemId(TECHBD_XML_BASE_URI + name);
                    input.setPublicId(publicId);
                    return input;
                }
            }));

            var start = java.lang.System.currentTimeMillis();
            var schema = sf.newSchema(new javax.xml.transform.stream.StreamSource(
                new java.io.StringReader(rootText), TECHBD_XML_BASE_URI + rootKey));
            logger.info("xmlCache: compiled XSD " + rootKey + " in " + (java.lang.System.currentTimeMillis() - start) + " ms");
            return schema;
        }
    }));
}

/**
	Compiled XSLT (javax.xml.transform.Templates). xsl:include/xsl:import are resolved from Lookup
	by file name without ".xslt" (same convention as the CCD channel).
	@param {String} lookupKey - exact Lookup key, e.g. "cda-phi-filter-epic" or "hl7v2-fhir-bundle.xslt"
*/
function getCompiledXslt(lookupKey) {
    var key = String(lookupKey);
    return xmlCache().computeIfAbsent('xslt:' + key, new java.util.function.Function({
        apply: function () {
            var text = lookupSchemaFileText(key);
            if (text == null) throw new Error("LookupManager: No XSLT found for key " + key);

            var tf = javax.xml.transform.TransformerFactory.newInstance();
            tf.setURIResolver(new javax.xml.transform.URIResolver({
                resolve: function (href, base) {
                    var incKey = xmlRefBaseName(href).replace(/\.xslt$/, '');
                    var incText = lookupSchemaFileText(incKey);
                    if (incText == null) throw new Error("LookupManager: No XSLT found for included key: " + incKey);
                    return new javax.xml.transform.stream.StreamSource(
                        new java.io.StringReader(incText), TECHBD_XML_BASE_URI + incKey + '.xslt');
                }
            }));

            var start = java.lang.System.currentTimeMillis();
            var templates = tf.newTemplates(new javax.xml.transform.stream.StreamSource(
                new java.io.StringReader(text), TECHBD_XML_BASE_URI + xmlRefBaseName(key)));
            logger.info("xmlCache: compiled XSLT " + key + " in " + (java.lang.System.currentTimeMillis() - start) + " ms");
            return templates;
        }
    }));
}

/**
	Drops all compiled artefacts (or one, e.g. "xsd:CDA.xsd" / "xslt:hl7v2-fhir-bundle.xslt").
	Only needed if a schema file is changed without a server restart.
*/
function clearXmlCache(cacheKey) {
    if (cacheKey) xmlCache().remove(String(cacheKey));
    else xmlCache().clear();
}
